//! Component scope: real blocking handle, socket lifetime and original error.
//! No business owner, receipt, Root intent or completion capability is created.

use super::*;
use crate::same_actor_q24_phase_gate::SameActorPhaseDeadline;
use pretty_assertions::assert_eq;
use std::future::Future;
use std::io::Read;
use std::os::unix::net::UnixStream;
use std::sync::mpsc;
use std::task::Context;
use std::task::Waker;
use std::time::Duration;

#[tokio::test]
async fn ready_consumer_join_survives_cancelled_recording_waiter_and_counts_once() {
    let gate = SameActorPhaseGate::from_original_deadline(
        SameActorPhaseDeadline::at_original_service_start(Duration::from_secs(10)).unwrap(),
    )
    .unwrap();
    let jobs = OriginalConsumerJobs::new(&gate);
    let (held, mut probe) = UnixStream::pair().unwrap();
    probe.set_nonblocking(true).unwrap();
    let (entered, started) = tokio::sync::oneshot::channel();
    let (release, released) = mpsc::sync_channel(1);
    let admission = jobs.reserve_original_consumer().unwrap();
    let handle = tokio::task::spawn_blocking(move || {
        let _held = held;
        entered.send(()).unwrap();
        released.recv_timeout(Duration::from_secs(5)).unwrap();
        Err(AgentdRootAuthorityError::Refused)
    });
    let job = admission.retain_original_session_consumer_handle(handle);
    tokio::time::timeout(Duration::from_secs(5), started)
        .await
        .unwrap()
        .unwrap();
    assert!(
        matches!(probe.read(&mut [0]), Err(error) if error.kind() == std::io::ErrorKind::WouldBlock)
    );
    let actual_join = {
        let state = job.state.lock().await;
        assert_eq!(state.observed, None);
        state.handle.as_ref().unwrap().clone()
    };
    let mut cancelled = Box::pin(jobs.receive_original_consumer(&job));
    let mut first = Box::pin(jobs.receive_original_consumer(&job));
    let mut second = Box::pin(jobs.receive_original_consumer(&job));
    {
        let mut context = Context::from_waker(Waker::noop());
        assert!(cancelled.as_mut().poll(&mut context).is_pending());
        assert!(first.as_mut().poll(&mut context).is_pending());
        assert!(second.as_mut().poll(&mut context).is_pending());
    }

    release.send(()).unwrap();
    let expected = Err(OriginalConsumerFailure::Owner(
        AgentdRootAuthorityError::Refused,
    ));
    assert_eq!(
        tokio::time::timeout(Duration::from_secs(5), actual_join)
            .await
            .unwrap(),
        expected
    );
    assert_eq!(probe.read(&mut [0]).unwrap(), 0);
    {
        // These waiters already borrowed the real handle before it finished.
        // Its Shared is now Ready; this lock pins their SECOND lock attempt.
        let state = job.state.lock().await;
        assert_eq!(state.observed, None);
        assert_eq!(state.handle.as_ref().unwrap().peek(), Some(&expected));
        let mut context = Context::from_waker(Waker::noop());
        assert!(cancelled.as_mut().poll(&mut context).is_pending());
        assert!(first.as_mut().poll(&mut context).is_pending());
        assert!(second.as_mut().poll(&mut context).is_pending());
        drop(cancelled);
        assert_eq!(state.observed, None);
        assert_eq!(state.handle.as_ref().unwrap().peek(), Some(&expected));
        let registry = jobs.state.lock().unwrap();
        assert_eq!((registry.registered, registry.joined), (1, 0));
        assert_eq!(registry.retained.len(), 1);
        assert!(Arc::ptr_eq(&registry.retained[0], &job));
    }
    // No lock is held across these awaits. Both record the same actual job;
    // the registry must remove that Arc and increment joined exactly once.
    let (first, second) = tokio::time::timeout(Duration::from_secs(5), async {
        tokio::join!(first, second)
    })
    .await
    .unwrap();
    assert_eq!(first, Err(AgentdRootAuthorityError::Refused));
    assert_eq!(second, Err(AgentdRootAuthorityError::Refused));
    {
        let state = job.state.lock().await;
        assert!(state.handle.is_none());
        assert_eq!(state.observed, Some(expected));
    }
    assert_eq!(
        jobs.receive_original_consumer(&job).await,
        Err(AgentdRootAuthorityError::Refused)
    );
    let summary = jobs.join_stopped_consumers().await.unwrap();
    assert_eq!((summary.registered, summary.joined), (1, 1));
    assert_eq!(
        summary.first_observed_failure,
        Some(OriginalConsumerFailure::Owner(
            AgentdRootAuthorityError::Refused
        ))
    );
    assert!(!summary.admission_poisoned);
    assert!(jobs.state.lock().unwrap().retained.is_empty());
}

//! Same-UID/synthetic-proof component using the actual phase Session fixture.
//! A real Session Drop and worker join are observed; no normal completion is made.

use super::*;
use crate::root_authority_session::lifecycle_support_tests::PhaseConnection;
use crate::root_authority_session::lifecycle_support_tests::join_peer;
use crate::root_authority_session::lifecycle_support_tests::phase_connection;
use pretty_assertions::assert_eq;
use std::future::Future;
use std::task::Context;
use std::task::Waker;
use std::time::Duration;

#[tokio::test]
async fn ready_session_worker_join_survives_cancelled_recording_waiter() {
    let slot = OriginalRootSessionCustodySlot::new();
    let PhaseConnection { session, peer, .. } = phase_connection(&slot).await;
    let session = session.unwrap();
    session.require_original_phase_task_custody(&slot).unwrap();
    let original = slot.state.lock().unwrap().original.as_ref().unwrap().clone();
    let actual_join = {
        let state = original.worker.lock().await;
        assert_eq!(state.observed, None);
        state.handle.as_ref().unwrap().clone()
    };
    assert!(!original.abort.is_finished());
    // On this current-thread runtime no worker can finish its scheduled abort
    // before the synchronous polls below borrow the same original Shared.
    // The actual Session's last field, not this test, marks it retired.
    drop(session);
    assert!(original.session_retired.load(Ordering::Acquire));
    let mut cancelled = Box::pin(slot.stop_and_join_retired_session_tasks());
    let mut first = Box::pin(slot.stop_and_join_retired_session_tasks());
    let mut second = Box::pin(slot.stop_and_join_retired_session_tasks());
    {
        let mut context = Context::from_waker(Waker::noop());
        assert!(cancelled.as_mut().poll(&mut context).is_pending());
        assert!(first.as_mut().poll(&mut context).is_pending());
        assert!(second.as_mut().poll(&mut context).is_pending());
    }

    let expected = tokio::time::timeout(Duration::from_secs(5), actual_join)
        .await
        .unwrap();
    assert_eq!(expected, OriginalRootWorkerTermination::Cancelled);
    assert!(original.abort.is_finished());
    {
        // Shared is already Ready. All three original callers must now wait
        // on this recording lock, with no worker handle removed from custody.
        let state = original.worker.lock().await;
        assert_eq!(state.observed, None);
        assert_eq!(state.handle.as_ref().unwrap().peek(), Some(&expected));
        let mut context = Context::from_waker(Waker::noop());
        assert!(cancelled.as_mut().poll(&mut context).is_pending());
        assert!(first.as_mut().poll(&mut context).is_pending());
        assert!(second.as_mut().poll(&mut context).is_pending());
        drop(cancelled);
        assert_eq!(state.observed, None);
        assert_eq!(state.handle.as_ref().unwrap().peek(), Some(&expected));
    }
    let (first, second) = tokio::time::timeout(Duration::from_secs(5), async {
        tokio::join!(first, second)
    })
    .await
    .unwrap();
    let first = first.unwrap();
    assert_eq!(second.unwrap(), first);
    let OriginalRootSessionJoinObservation::Joined {
        slot_poisoned,
        worker,
        consumers,
        ..
    } = first
    else {
        panic!("actual Session worker was not retained");
    };
    assert!(!slot_poisoned);
    assert_eq!(worker, expected);
    assert_eq!(consumers.joined, consumers.registered);
    {
        let state = original.worker.lock().await;
        assert!(state.handle.is_none());
        assert_eq!(state.observed, Some(expected));
    }
    assert_eq!(
        slot.stop_and_join_retired_session_tasks().await.unwrap(),
        first
    );
    drop(original);
    drop(slot);
    join_peer(peer).await;
}
